import { splitProps, type JSX, type ParentProps } from 'solid-js';
import { buttonGroupStyleKeys, getButtonGroupStyleKeys } from '../lib/core';
import type { ButtonGroupBaseProps, ButtonGroupSeparatorBaseProps } from '../lib/core';
import styles from './button-group.module.scss';

export interface ButtonGroupProps extends JSX.HTMLAttributes<HTMLDivElement>, ButtonGroupBaseProps {}

export function ButtonGroup(props: ParentProps<ButtonGroupProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'orientation']);
	const orientation = () => local.orientation ?? 'horizontal';
	const styleKeys = () => getButtonGroupStyleKeys(orientation());

	return (
		<div
			{...rest}
			role="group"
			data-slot="button-group"
			data-orientation={orientation()}
			class={`${styles[styleKeys().base]} ${styles[styleKeys().orientation]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}

export interface ButtonGroupTextProps extends JSX.HTMLAttributes<HTMLDivElement> {}

export function ButtonGroupText(props: ParentProps<ButtonGroupTextProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<div {...rest} class={`${styles[buttonGroupStyleKeys.text]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}

export interface ButtonGroupSeparatorProps extends JSX.HTMLAttributes<HTMLDivElement>, ButtonGroupSeparatorBaseProps {}

export function ButtonGroupSeparator(props: ButtonGroupSeparatorProps) {
	const [local, rest] = splitProps(props, ['class', 'orientation']);
	return (
		<div
			{...rest}
			role="none"
			aria-hidden="true"
			data-slot="button-group-separator"
			data-orientation={local.orientation ?? 'vertical'}
			class={`${styles[buttonGroupStyleKeys.separator]} ${local.class ?? ''}`}
		/>
	);
}

export default ButtonGroup;

@use '../../../styles/variables/colors' as *;

.buttonGroup {
	position: var(--tile-button-group-position, static);
	isolation: var(--tile-button-group-isolation, auto);
	display: flex;
	width: fit-content;
	align-items: stretch;

	> * {
		&:focus-visible {
			position: relative;
			z-index: var(--tile-button-group-focus-z-index, 1);
		}
	}

	// 嵌套按钮组
	[data-slot='button-group'] {
		gap: $spacing-2;
	}

	// 排列方向
	&.orientationHorizontal {
		flex-direction: row;

		// 直接子元素之间的连接样式
		> *:not(:first-child) {
			border-left: var(--tile-button-group-seam-border, none);
			margin-inline-start: var(--tile-button-group-seam-overlap, 0);
			border-top-left-radius: 0;
			border-bottom-left-radius: 0;
		}

		> *:not(:last-child) {
			border-top-right-radius: 0;
			border-bottom-right-radius: 0;
		}
	}

	&.orientationVertical {
		flex-direction: column;

		> *:not(:first-child) {
			border-top: none;
			border-top-left-radius: 0;
			border-top-right-radius: 0;
		}

		> *:not(:last-child) {
			border-bottom-right-radius: 0;
			border-bottom-left-radius: 0;
		}
	}
}

.text {
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: var(--tile-button-group-radius, $radius);
	border: 1px solid var(--tile-button-group-border, $border);
	background-color: var(--tile-button-group-background, $muted);
	padding: var(--tile-button-group-padding, 0 $spacing-4);
	font-size: var(--tile-button-group-font-size, $text-sm);
	font-weight: var(--tile-button-group-font-weight, $font-medium);
	box-shadow: var(--tile-button-group-shadow, $shadow-sm);

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}

.separator {
	position: relative;
	align-self: stretch;
	margin: 0;
	background-color: var(--tile-button-group-separator, $input);

	&[data-orientation='vertical'] {
		height: auto;
		width: 1px;
	}

	&[data-orientation='horizontal'] {
		height: 1px;
		width: auto;
	}
}
